import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/environment-variables.md","filePath":"develop/environment-variables.md","lastUpdated":null}'),d={name:"develop/environment-variables.md"};function n(i,e,c,s,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/environment-variables.md" target="_blank" rel="noreferrer"><code>.agents/environment-variables.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h1><h2 id="single-source-of-truth" tabindex="-1">Single Source of Truth <a class="header-anchor" href="#single-source-of-truth" aria-label="Permalink to &quot;Single Source of Truth&quot;">​</a></h2><p>All env vars live in <code>packages/env/.env</code> (copy from <code>.env.example</code>). Validated by Zod at import time via <code>@t3-oss/env-core</code>.</p><h2 id="three-scoped-objects" tabindex="-1">Three Scoped Objects <a class="header-anchor" href="#three-scoped-objects" aria-label="Permalink to &quot;Three Scoped Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Scope</th></tr></thead><tbody><tr><td><code>ENV_SERVER</code></td><td>Server-only (<code>apps/server</code>, <code>apps/worker</code>, SSR and backend packages)</td></tr><tr><td><code>ENV_WEB_ISOMORPHIC</code></td><td>Client + server (<code>apps/web</code>)</td></tr><tr><td><code>ENV_WEB_SERVER</code></td><td>Web server-only</td></tr></tbody></table><h2 id="client-exposure-rule" tabindex="-1">Client Exposure Rule <a class="header-anchor" href="#client-exposure-rule" aria-label="Permalink to &quot;Client Exposure Rule&quot;">​</a></h2><p>Only vars prefixed with <code>VITE_</code> are available on the client (<code>import.meta.env</code>). Server-only vars (<code>DATABASE_URL</code>, <code>BETTER_AUTH_SECRET</code>) must never be exposed to the client.</p><h2 id="when-adding-updating-env-vars" tabindex="-1">When Adding/Updating Env Vars <a class="header-anchor" href="#when-adding-updating-env-vars" aria-label="Permalink to &quot;When Adding/Updating Env Vars&quot;">​</a></h2><p>Update only the surfaces that consume or propagate the value, and keep them synchronized:</p><ol><li><code>packages/env/src/</code> — add Zod validation to the appropriate scoped object</li><li><code>packages/env/.env.example</code> and <code>.env.docker.example</code> — add safe local/deployment placeholders</li><li><code>docker-compose.yaml</code> and <code>docker-compose.coolify.yaml</code> — propagate to affected runtime services</li><li>Relevant Dockerfile <code>ARG</code>/<code>ENV</code> only when the value is genuinely required at image build time; do not bake runtime secrets into images</li><li><code>packages/env/README.md</code> or the owning package/runbook — document scope, requirement, and production behavior</li><li><code>apps/web/vite.config.ts</code> build dependencies only for web build-time values; never put server secrets in <code>define</code></li></ol><p>Missing any of these causes build or runtime failures with no obvious error message.</p><p>Env docs and templates must mirror the validated schema in <code>packages/env/src/</code>. Do not invent, retain, or document env vars that are not actually read there. If a setting is code-owned, document it as code-owned instead of adding a new env knob.</p><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><ul><li><code>z.stringbool()</code> is used for boolean env vars (parses &quot;true&quot;/&quot;false&quot; strings)</li><li>Dev defaults exist for most <code>VITE_*</code> vars; <code>DATABASE_URL</code> and <code>BETTER_AUTH_SECRET</code> are always required</li><li>Production-only invariants live in <code>packages/env/src/server/production-guards.ts</code> (Redis, mail delivery, metrics token, provider credential completeness). Update tests there when changing a guarded provider or security setting.</li><li>Each env file logs loading with <code>console.debug</code> — check terminal output for validation errors</li></ul>',15)])])}const v=o(d,[["render",n]]);export{u as __pageData,v as default};
